// ==========================================
// CLIP DATA & STATS HELPER
// ==========================================
// Reads `src/config/clips.generated.json` (generated by `npm run sync`),
// falling back to `src/config/clips.js` if needed.
// Filters out any empty TODO slots (`url: ""`) and computes all real statistics
// dynamically so zero hardcoded or invented numbers ever appear on the site.

import generatedData from './clips.generated.json';
import { clipsList as manualFallbackClips } from './clips';

export function getActiveClips() {
  const rawList =
    generatedData && Array.isArray(generatedData.clips) && generatedData.clips.length > 0
      ? generatedData.clips
      : manualFallbackClips || [];

  // Never render any entry with an empty URL
  return rawList.filter(clip => clip && typeof clip.url === 'string' && clip.url.trim() !== '');
}

export function getSyncMeta() {
  const clips = getActiveClips();
  const generatedAt = generatedData?.meta?.generatedAt || '2026-10-31';
  const viewsAsOf =
    generatedData?.meta?.viewsAsOf ||
    clips.find(c => c.viewsAsOf)?.viewsAsOf ||
    '2026-10-31';

  // Compute total views strictly from clips that have a verified numeric view count
  const totalViews = clips.reduce((sum, clip) => {
    return sum + (typeof clip.views === 'number' && !isNaN(clip.views) ? clip.views : 0);
  }, 0);

  const uniquePlatforms = Array.from(new Set(clips.map(c => (c.platform || '').toLowerCase()).filter(Boolean)));
  const uniqueAccounts = Array.from(new Set(clips.map(c => c.account).filter(Boolean)));

  return {
    generatedAt,
    viewsAsOf,
    totalClips: clips.length,
    totalViews,
    uniquePlatforms,
    uniqueAccounts
  };
}

export function formatViewCount(views) {
  if (typeof views !== 'number' || isNaN(views)) return null;
  if (views >= 1000000) {
    const val = (views / 1000000).toFixed(1).replace(/\.0$/, '');
    return `${val}M`;
  }
  if (views >= 1000) {
    const val = (views / 1000).toFixed(1).replace(/\.0$/, '');
    return `${val}K`;
  }
  return views.toLocaleString();
}
